struct PwhlLogo { const char* abbr; const uint16_t* data; };
static const PwhlLogo PWHL_LOGOS[] = {
  {"BOS", LOGO_PWHL_BOS},
  {"MIN", LOGO_PWHL_MIN},
  {"MTL", LOGO_PWHL_MTL},
  {"NY", LOGO_PWHL_NY},
  {"OTT", LOGO_PWHL_OTT},
  {"SEA", LOGO_PWHL_SEA},
  {"TOR", LOGO_PWHL_TOR},
  {"VAN", LOGO_PWHL_VAN},
  {"DET", LOGO_PWHL_DET},
  {"HAM", LOGO_PWHL_HAM},
  {"VGS", LOGO_PWHL_VGS},
  {"SJ", LOGO_PWHL_SJ},
};
#define PWHL_LOGO_COUNT (sizeof(PWHL_LOGOS)/sizeof(PWHL_LOGOS[0]))

// nullptr si l'equipe n'a pas (encore) de logo : l'appelant affiche son code en texte.
static const uint16_t* pwhlLogoByAbbrev(const char* abbr){
  for(int i=0;i<(int)PWHL_LOGO_COUNT;i++) if(strcmp(PWHL_LOGOS[i].abbr, abbr)==0) return PWHL_LOGOS[i].data;
  return nullptr;
}

